namespace STSS.Core.Domain.Entities.Audit;

/// <summary>
/// Represents an audit log entry that records a change made to an entity.
/// </summary>
/// <remarks>
/// Audit log entries provide a historical record of create, update,
/// soft-delete, restore, or delete operations performed against
/// business entities in the system.
/// </remarks>
public class AuditLog
{
    /// <summary>
    /// Gets or sets the primary key for the audit log entry.
    /// </summary> by6
    public int Id { get; set; }

    /// <summary>
    /// Gets or sets the identifier of the entity affected by the change.
    /// </summary>
    /// <remarks>
    /// This value is stored as a string to support multiple entity key types,
    /// such as <see cref="Guid"/>, <see cref="int"/>, or other key formats.
    /// </remarks>
    public string EntityId { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the name of the entity type affected by the change.
    /// </summary>
    public string EntityName { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the type of change that occurred.
    /// </summary>
    /// <remarks>
    /// Examples include Create, Update, SoftDelete, Restore, and Delete.
    /// </remarks>
    public string ChangeType { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the date and time the change occurred.
    /// </summary>
    public DateTime OccurredAt { get; set; }

    /// <summary>
    /// Gets or sets the identifier of the user or process that made the change.
    /// </summary>
    public string UserId { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets additional details describing the change.
    /// </summary>
    /// <remarks>
    /// This may contain a summary of changed fields, serialized data,
    /// or other diagnostic information about the operation.
    /// </remarks>
    public string Details { get; set; } = string.Empty;
}
